CREATE OR REPLACE FUNCTION public.measurement_attach_support(p_task_id uuid,p_customer_id uuid,p_backfill_at timestamptz DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS $$
DECLARE t product_measurement_tasks%ROWTYPE;l record;v_name text;v_key text;v_conv uuid;v_nick text;
BEGIN
 SELECT * INTO t FROM product_measurement_tasks WHERE id=p_task_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM product_measurement_requesters WHERE task_id=t.id AND customer_id=p_customer_id) THEN RAISE EXCEPTION 'measurement_requester_required'; END IF;
 IF t.status NOT IN ('pending','claimed') OR t.listing_id IS NULL OR t.location_id IS NULL THEN RETURN NULL; END IF;
 SELECT id,location_id,title,price INTO l FROM commerce_listings WHERE id=t.listing_id;IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT name INTO v_name FROM inv_skus WHERE id=t.sku_id;
 SELECT sc.id INTO v_conv FROM product_measurement_requesters q JOIN support_conversations sc ON sc.id=q.conversation_id WHERE q.task_id=t.id AND q.customer_id=p_customer_id AND sc.customer_id=p_customer_id AND sc.location_id=t.location_id FOR UPDATE OF sc;
 v_key:='product:'||t.listing_id::text;
 IF v_conv IS NULL THEN SELECT id INTO v_conv FROM support_conversations WHERE customer_id=p_customer_id AND context_key=v_key AND location_id=t.location_id AND status IN ('open','pending') ORDER BY created_at,id LIMIT 1 FOR UPDATE; END IF;
 IF v_conv IS NULL AND EXISTS(SELECT 1 FROM support_conversations WHERE customer_id=p_customer_id AND context_key=v_key AND status IN ('open','pending')) THEN v_key:='measurement:'||t.id::text||':location:'||t.location_id::text; END IF;
 IF v_conv IS NULL THEN
 SELECT coalesce(nullif(nickname,''),'顾客') INTO v_nick FROM commerce_customers WHERE id=p_customer_id;
 INSERT INTO support_conversations(customer_id,location_id,context_key,context,channel,title,topic) VALUES(p_customer_id,t.location_id,v_key,jsonb_build_object('type','product','id',l.id,'title',l.title,'price',l.price),'native',coalesce(v_nick,'顾客')||' 的咨询','product') ON CONFLICT(customer_id,context_key) WHERE context_key IS NOT NULL AND status IN ('open','pending') DO NOTHING RETURNING id INTO v_conv;
 IF v_conv IS NULL THEN SELECT id INTO v_conv FROM support_conversations WHERE customer_id=p_customer_id AND context_key=v_key AND location_id=t.location_id AND status IN ('open','pending') LIMIT 1 FOR UPDATE; END IF;
 END IF;
 IF v_conv IS NULL OR NOT EXISTS(SELECT 1 FROM support_conversations WHERE id=v_conv AND customer_id=p_customer_id AND location_id=t.location_id) THEN RAISE EXCEPTION 'measurement_support_route_conflict'; END IF;
 INSERT INTO support_messages(conversation_id,sender_type,sender_name,body,internal,delivery_status,client_op_id,measurement_task_id,card_kind) VALUES(v_conv,'system','系统',CASE WHEN p_backfill_at IS NOT NULL THEN '【历史申请补录·原申请于 '||to_char(p_backfill_at AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD HH24:MI')||'】' ELSE '' END||'顾客申请测量商品尺寸：'||coalesce(v_name,l.title,'商品'),false,'sent','measurement_request:'||t.id::text,t.id,'measurement_request') ON CONFLICT DO NOTHING;
 UPDATE product_measurement_requesters SET conversation_id=v_conv WHERE task_id=t.id AND customer_id=p_customer_id;
 RETURN v_conv;
END $$;
CREATE OR REPLACE FUNCTION public.tg_measurement_task_completed_support() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS $$
BEGIN
 INSERT INTO support_messages(conversation_id,sender_type,sender_name,body,internal,delivery_status,client_op_id,measurement_task_id,card_kind)
 SELECT DISTINCT c.id,'system','系统','商品尺寸已测量，可在商品详情查看实测尺寸。',false,'sent','measurement_completed:'||NEW.id::text,NEW.id,'measurement_completed' FROM support_messages m JOIN support_conversations c ON c.id=m.conversation_id JOIN product_measurement_requesters q ON q.task_id=NEW.id AND q.customer_id=c.customer_id AND q.conversation_id=c.id WHERE m.measurement_task_id=NEW.id AND m.card_kind='measurement_request' AND c.location_id=NEW.location_id ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.support_needs_reply(p_conversation_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$
 SELECT coalesce((SELECT c.status<>'closed' AND (c.waiting_since IS NOT NULL OR (c.primary_agent_id IS NULL AND (SELECT m.sender_type='customer' FROM support_messages m WHERE m.conversation_id=c.id AND NOT m.internal AND m.delivery_status='sent' AND m.sender_type IN ('customer','staff') ORDER BY m.created_at DESC,m.id DESC LIMIT 1))) FROM support_conversations c WHERE c.id=p_conversation_id),false)
$$;
CREATE OR REPLACE FUNCTION public.support_pending_state(p_conversation_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$
 WITH c AS(SELECT * FROM support_conversations WHERE id=p_conversation_id),n AS(SELECT count(DISTINCT t.id) cnt FROM support_messages m JOIN product_measurement_tasks t ON t.id=m.measurement_task_id JOIN c ON c.id=m.conversation_id AND c.location_id=t.location_id JOIN product_measurement_requesters q ON q.task_id=t.id AND q.customer_id=c.customer_id AND q.conversation_id=c.id WHERE m.card_kind='measurement_request' AND t.status IN ('pending','claimed')) SELECT jsonb_build_object('needs_reply',public.support_needs_reply(p_conversation_id),'pending_measurement_count',cnt,'pending_action',public.support_needs_reply(p_conversation_id) OR cnt>0) FROM n
$$;
CREATE OR REPLACE FUNCTION public.handheld_work_items(p_user_id uuid,p_location_ids uuid[],p_include_unlocated boolean DEFAULT false,p_limit integer DEFAULT 50,p_cursor_ts timestamptz DEFAULT NULL,p_cursor_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$
 WITH locs AS(SELECT coalesce(p_location_ids,'{}'::uuid[]) ids),cards AS(
 SELECT m.conversation_id,m.measurement_task_id,t.created_at,t.listing_id,t.sku_id FROM support_messages m JOIN product_measurement_tasks t ON t.id=m.measurement_task_id JOIN support_conversations sc ON sc.id=m.conversation_id AND sc.location_id=t.location_id JOIN product_measurement_requesters q ON q.task_id=t.id AND q.customer_id=sc.customer_id AND q.conversation_id=sc.id WHERE m.card_kind='measurement_request' AND t.status IN ('pending','claimed')),
 sup AS(SELECT sc.*,(SELECT count(*) FROM cards c WHERE c.conversation_id=sc.id) pmc,(SELECT min(c.created_at) FROM cards c WHERE c.conversation_id=sc.id) card_at,(SELECT c.sku_id FROM cards c WHERE c.conversation_id=sc.id ORDER BY c.created_at LIMIT 1) card_sku,public.support_needs_reply(sc.id) needs_reply FROM support_conversations sc,locs WHERE sc.location_id=ANY(locs.ids) OR(p_include_unlocated AND sc.location_id IS NULL)),
 all_items AS(
 SELECT s.id,'support'::text type,'customers'::text cat,coalesce(least(s.waiting_since,s.card_at),s.waiting_since,s.card_at,s.created_at) sort_ts,coalesce(s.title,'客户咨询') title,concat_ws(' · ',CASE WHEN s.needs_reply THEN CASE WHEN s.primary_agent_id IS NULL THEN '待接待' ELSE '待回复' END END,CASE WHEN s.pmc>0 THEN '尺寸申请 '||s.pmc||' 件' END) description,'support_conversation'::text action,s.id target_id,s.card_sku sku_id,s.id conversation_id,CASE WHEN s.context->>'type'='product' THEN s.context->>'id' END listing_id FROM sup s WHERE s.needs_reply OR s.pmc>0
 UNION ALL SELECT t.id,'measurement','customers',t.created_at,'尺寸测量 '||coalesce(k.name,''),CASE WHEN t.status='claimed' THEN '测量中' ELSE '顾客申请测量，待处理' END,'measurement_task',t.id,t.sku_id,NULL::uuid,t.listing_id::text FROM product_measurement_tasks t LEFT JOIN inv_skus k ON k.id=t.sku_id,locs WHERE t.status IN ('pending','claimed') AND t.location_id=ANY(locs.ids) AND NOT EXISTS(SELECT 1 FROM cards c WHERE c.measurement_task_id=t.id)
 UNION ALL SELECT f.id,'commerce_pick','orders',f.created_at,'商城拣货 '||coalesce(o.order_no,f.code),CASE WHEN o.fulfillment_method='pickup' THEN '自提待备货/领取' WHEN f.status IN ('picked','packing','packed','handover_ready') THEN '待发货/交接' WHEN f.status='picking' THEN '拣货中' ELSE '待备货/异常处理' END,'fulfillment_detail',f.id,NULL::uuid,NULL::uuid,NULL::text FROM fulfillments f JOIN commerce_orders o ON o.id=f.order_id,locs WHERE f.status IN ('unallocated','allocated','picking','picked','packing','packed','handover_ready','exception') AND f.location_id=ANY(locs.ids) AND o.order_status NOT IN ('cancelled','closed') AND o.payment_status IN ('paid','refund_pending','partially_refunded')
 UNION ALL SELECT x.id,CASE WHEN x.status IN ('shipped','in_transit') THEN 'transfer_in' ELSE 'transfer_out' END,'internal',coalesce(x.shipped_at,x.created_at),'调拨入库 '||x.code,'共 '||x.qty||' 件，待验收入库','transfer_detail',x.id,NULL::uuid,NULL::uuid,NULL::text FROM stock_transfers x,locs WHERE(x.status IN ('shipped','in_transit') AND x.to_location_id=ANY(locs.ids)) OR(x.status IN ('draft','approved','failed') AND x.from_location_id=ANY(locs.ids))
 UNION ALL SELECT st.id,'stocktake','internal',coalesce(st.opened_at,st.created_at),'盘点 '||st.code,'盘点进行中，待提交','stocktake_detail',st.id,NULL::uuid,NULL::uuid,NULL::text FROM stocktakes st,locs WHERE st.status IN ('open','scanning','submitted') AND st.location_id=ANY(locs.ids)
 UNION ALL SELECT a.id,'after_sale','orders',a.created_at,'售后 '||coalesce(a.after_sale_no,''),'待处理售后','after_sale_detail',a.id,NULL::uuid,NULL::uuid,NULL::text FROM commerce_after_sales a,locs WHERE a.status IN ('requested','store_reviewing','store_received','inspecting','refund_pending') AND a.location_id=ANY(locs.ids)
 UNION ALL SELECT z.id,'stock_sync','system',z.created_at,'库存同步失败','待核查','sync_detail',z.id,NULL::uuid,NULL::uuid,NULL::text FROM youzan_stock_sync_queue z WHERE z.status='failed' AND EXISTS(SELECT 1 FROM inv_locations l,locs WHERE l.id=ANY(locs.ids) AND l.shop_id=z.shop_id)
 UNION ALL SELECT z.id,'channel_sync','system',z.created_at,'渠道同步失败','待核查','sync_detail',z.id,NULL::uuid,NULL::uuid,NULL::text FROM channel_sync_outbox z WHERE z.status IN ('failed','dead','dead_letter') AND(EXISTS(SELECT 1 FROM inv_locations l,locs WHERE l.id=ANY(locs.ids) AND l.shop_id=z.shop_id) OR(p_include_unlocated AND z.shop_id IS NULL))),
 counts AS(SELECT count(*) FILTER(WHERE cat='customers') customers,count(*) FILTER(WHERE cat='internal') internal,count(*) FILTER(WHERE cat='orders') orders,count(*) FILTER(WHERE cat='system') system FROM all_items),
 page AS(SELECT * FROM all_items WHERE p_cursor_ts IS NULL OR(sort_ts,id)>(p_cursor_ts,p_cursor_id) ORDER BY sort_ts,id LIMIT greatest(coalesce(p_limit,50),0)+1),numbered AS(SELECT p.*,row_number() OVER(ORDER BY sort_ts,id) rn FROM page p)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'type',type,'title',title,'description',description,'sort_ts',sort_ts,'action',action,'target_id',target_id,'sku_id',sku_id,'conversation_id',conversation_id,'listing_id',listing_id) ORDER BY rn) FROM numbered WHERE rn<=greatest(coalesce(p_limit,50),0)),'[]'::jsonb),'has_more',(SELECT count(*) FROM numbered)>greatest(coalesce(p_limit,50),0),'last_ts',(SELECT sort_ts FROM numbered WHERE rn=greatest(coalesce(p_limit,50),0)),'last_id',(SELECT id FROM numbered WHERE rn=greatest(coalesce(p_limit,50),0)),'counts',(SELECT jsonb_build_object('customers',customers,'internal',internal,'orders',orders,'system',system,'total',customers+internal+orders+system) FROM counts))
$$;
CREATE OR REPLACE FUNCTION public.handheld_pending_counts(p_user_id uuid,p_location_ids uuid[],p_include_unlocated boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$ SELECT public.handheld_work_items(p_user_id,p_location_ids,p_include_unlocated,0,NULL,NULL)->'counts' $$;
REVOKE ALL ON FUNCTION public.support_needs_reply(uuid),public.support_pending_state(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.support_needs_reply(uuid),public.support_pending_state(uuid) TO service_role;
ALTER TABLE public.product_measurement_requesters ENABLE TRIGGER trg_measurement_requester_support;
ALTER TABLE public.product_measurement_tasks ENABLE TRIGGER trg_measurement_task_completed_support;